use super::*;

/// The `bsc graph imports migrate` core: on canonically-normalized `code`, pull the leading canonical
/// import block out into specs and return the stored body (doc-comment + any floor imports + body).
/// [`bsc_record::imports_fmt::body_with_imports`] over `(body, specs)` reproduces `code` byte-for-byte,
/// so the materializer re-renders the normalized module exactly — which is what makes the two-ref
/// emit-parity a zero diff. Run it only AFTER `normalize`, so the block it strips is already canonical.
pub fn migrate_code(code: &str) -> (String, Vec<ImportSpec>) {
    let (body, fmt) = bsc_record::imports_fmt::strip_imports(code);
    (body, fmt.iter().map(from_fmt).collect())
}
